function checkBudget(){const input=$('#bq-budget-value'),err=$('#bq-budget-error');if(input)input.setAttribute('aria-invalid',String(!validBudget()));if(err)err.textContent=validBudget()?'':'أدخل ميزانية من ٦٠ إلى ١٬٥٠٠ ريال للمتابعة.';return validBudget();}
