function makeProposal(){if(!validBudget()){step=0;renderStep(true);checkBudget();return;}const color=state.occasion==='love'?'red':state.occasion==='graduation'?'white':state.occasion==='birthday'?'apricot':'pink';const first=state.occasion==='birthday'?'gerbera':'rose';const p={ribbon:{...state.ribbon},spread:state.spread,occasion:state.occasion,budget:state.budget,flowers:emptyFlowers(),wrap:'paper',extras:[],message:state.message,stems:[]};const budget=state.budget-15,unit=flowers.find(f=>f.id===first).price,q1=Math.min(18,Math.max(1,Math.floor(budget*.65/unit))),q2=Math.min(12,Math.max(0,Math.floor((budget-q1*unit)/8)));for(let i=0;i<q1;i++)p.stems.push(newStem(first,color,300,215));for(let i=0;i<q2;i++)p.stems.push(newStem('carnation','white',300,215));distribute(p.stems);syncCounts(p);p.flowers[first].color=color;proposal=p;renderProposal();}
function renderProposal(){const el=$('#bq-suggestion');el.hidden=!proposal;if(!proposal)return;el.innerHTML=`<strong>اقتراح لـ${occasions[state.occasion]}</strong><p>${flowers.filter(f=>proposal.flowers[f.id].qty).map(f=>num(proposal.flowers[f.id].qty)+' '+f.name).join('، ')}، مع ورق مطفي.<br>المجموع: ${money(costs(proposal).total)}</p><p>سيستبدل الورد وترتيبه والتغليف والإضافات، ويحافظ على رسالتك. تقدر تحرّك أي وردة بعد اعتماده.</p><button type="button" class="bq-action is-secondary" id="bq-apply-proposal">اعتمد هذا الاقتراح</button>`;}
const canvas=$('#bq-canvas'),ctx=canvas.getContext('2d'),images={},imageStatus={},tints=new Map();
const imageFiles={classic:'assets/bouquet-blooms.png',new:'assets/bouquet-blooms-extra.png',wrap:'assets/bouquet-wraps-refined.png',wrapExtra:'assets/bouquet-wraps-extra-refined.png',ribbon:'assets/bouquet-ribbons.png'};
