function flowerSprite(f,color){const key=f.id+color;if(tints.has(key))return tints.get(key);const atlas=images[f.atlas];if(imageStatus[f.atlas]!=='ready')return null;const sw=atlas.naturalWidth/3,sh=atlas.naturalHeight;const out=document.createElement('canvas');out.width=sw;out.height=sh;const c=out.getContext('2d');c.drawImage(atlas,f.cell*sw,0,sw,sh,0,0,sw,sh);if(color!=='white'){c.globalCompositeOperation='multiply';c.fillStyle=colors.find(x=>x.id===color).hex;c.fillRect(0,0,sw,sh);c.globalCompositeOperation='destination-in';c.drawImage(atlas,f.cell*sw,0,sw,sh,0,0,sw,sh);}tints.set(key,out);return out;}
