function pointFromEvent(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*600/r.width,y:(e.clientY-r.top)*600/r.height};}
function hitTest(point){return state.stems.slice().sort((a,b)=>b.y-a.y).find(p=>Math.hypot(point.x-p.x,point.y-p.y)<flowers.find(f=>f.id===p.kind).size*.48);}
