canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;if(step===2&&state.extras.includes('ribbon')){const point=pointFromEvent(e);if(hitRibbon(point)){e.preventDefault();ribbonDrag={start:{...state.ribbon},dx:point.x-state.ribbon.x,dy:point.y-state.ribbon.y,moved:false};canvas.setPointerCapture(e.pointerId);canvas.style.cursor='grabbing';}return;}if(step!==1)return;e.preventDefault();const point=pointFromEvent(e);hover=null;if(Math.hypot(point.x-(area.x+area.rx),point.y-area.y)<=34){resizeDrag={scale:state.spread,stems:state.stems.map(p=>({...p}))};canvas.setPointerCapture(e.pointerId);return;}if(mode==='place'){placeFlower(point);return;}const hit=hitTest(point);selected=hit?.id||null;if(hit){drag={id:hit.id,dx:point.x-hit.x,dy:point.y-hit.y,moved:false,start:{x:hit.x,y:hit.y}};canvas.setPointerCapture(e.pointerId);}renderEditor();drawPreview();if(!hit)feedback('اضغط على وردة لاختيارها، ثم اسحبها.');});
